import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
})

import React, { useState } from 'react';

interface Restaurant {
  id: number;
  name: string;
  cuisine: string;
  votes: number;
}

const INITIAL_RESTAURANTS: Restaurant[] = [
  { id: 1, name: 'Pizza Palace', cuisine: 'Italian', votes: 0 },
  { id: 2, name: 'Sushi Zen', cuisine: 'Japanese', votes: 0 },
  { id: 3, name: 'Burger Bliss', cuisine: 'American', votes: 0 },
];

const App: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>(INITIAL_RESTAURANTS);
  const [hasVoted, setHasVoted] = useState(false);

  const handleVote = (id: number) => {
    setRestaurants(prev =>
      prev.map(r => (r.id === id ? { ...r, votes: r.votes + 1 } : r))
    );
    setHasVoted(true);
  };

  return (
    <div className="container">
      <h1>Vote for Your Favorite Restaurant!</h1>
      <p>{hasVoted ? "Thank you for voting!" : "Choose one of the following restaurants:"}</p>

      <div className="restaurant-list">
        {restaurants.map(restaurant => (
          <div key={restaurant.id} className="restaurant-card">
            <h2>{restaurant.name}</h2>
            <p>{restaurant.cuisine}</p>
            <div className="vote-count">Votes: {restaurant.votes}</div>
            {!hasVoted && (
              <button onClick={() => handleVote(restaurant.id)}>Vote</button>
            )}
          </div>
        ))}
      </div>

      {hasVoted && (
        <button className="reset-btn" onClick={() => setHasVoted(false)}>Vote Again</button>
      )}
    </div>
  );
};

export default App;

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-size: 16px;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
}

#root {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.restaurant-list {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  justify-content: center;
}

.restaurant-card {
  border: 1px solid #646464;
  border-radius: 12px;
  padding: 2rem;
  width: 200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  background-color: #1a1a1a;
  transition: transform 0.2s;
}

.restaurant-card:hover {
  transform: scale(1.05);
}

.vote-count {
  font-weight: bold;
  font-size: 1.2rem;
  margin-bottom: 1rem;
}

button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #646cff;
  color: white;
  cursor: pointer;
  transition: background-color 0.25s;
}

button:hover {
  background-color: #535bf2;
}

.reset-btn {
  background-color: #444;
}

.reset-btn:hover {
  background-color: #555;
}
